// Functional CAN 2.0 controller/breakout. The two bus pins include an ideal
// transceiver; wire CANH-to-CANH and CANL-to-CANL. No analog EMC/termination model.
export class MCP2515 {
 constructor(){this.reset();}
 reset(){this.r=new Uint8Array(256);this.r[14]=128;this.r[15]=135;this.frames=0;this.received=0;this.pending=new Map();this.generation=(this.generation||0)+1;this.select();}
 get mode(){return this.r[14]>>5;}
 get bitrate(){const r=this.r;return(this.oscillator??16000000)/(2*((r[42]&63)+1)*(1+(r[41]&7)+1+((r[41]>>3)&7)+1+(r[41]&128?(r[40]&7)+1:Math.max(2,((r[41]>>3)&7)+1))));}
 setEnvironment(p){this.oscillator=(p.oscillatorMHz??16)*1000000;}
 select(){this.tx=255;this.op=null;this.phase=0;this.addr=0;this.mask=0;this.clearRX=null;}
 deselect(){if(this.clearRX!==null)this.r[44]&=~(1<<this.clearRX);}
 frame(index){const a=0x31+index*16,r=this.r,extended=!!(r[a+1]&8),standard=r[a]*8+(r[a+1]>>5);return{index,extended,id:extended?standard*262144+((r[a+1]&3)<<16)+(r[a+2]<<8)+r[a+3]:standard,rtr:!!(r[a+4]&64),dlc:Math.min(8,r[a+4]&15),raw:Array.from(r.slice(a,a+13)),generation:this.generation};}
 transmit(index){if(this.mode!==0&&this.mode!==2)return;this.r[0x30+index*16]=(this.r[0x30+index*16]&3)|8;const frame=this.frame(index);this.pending.set(index,frame);if(this.onRequest)this.onRequest();else if(this.mode===2){this.receive(frame,true);this.finish(frame,true);}}
 finish(f,ack){if(f.generation!==this.generation||!this.pending.has(f.index))return;const a=0x30+f.index*16;if(ack){this.pending.delete(f.index);this.r[a]&=~0x78;this.r[44]|=4<<f.index;this.frames++;this.r[28]=Math.max(0,this.r[28]-1);}else{this.r[a]|=16;this.r[28]=Math.min(255,this.r[28]+8);this.r[45]=(this.r[45]&0xc0)|(this.r[28]>=96?5:0)|(this.r[28]>=128?16:0)|(this.r[28]===255?32:0);if(this.r[15]&8){this.pending.delete(f.index);this.r[a]&=~8;}}}
 matches(f,filter,mask){const r=this.r,extended=!!(r[filter+1]&8);if((r[mask+1]&8)&&extended!==f.extended)return false;for(let i=0;i<4;i++){const bits=i===1?0xe3:255;if(((r[filter+i]^(i>=2&&!f.extended?(f.raw[5+i-2]??0):f.raw[i]))&r[mask+i]&bits)!==0)return false;}return true;}
 receive(f,loopback=false){if(!loopback&&![0,3].includes(this.mode))return false;const r=this.r;let rollover=false;for(let index=0;index<2;index++){const a=0x60+index*16,mode=(r[a]>>5)&3,filters=index?[0x10,0x14,0x18,0x1c]:[0,4],mask=0x20+index*4,accepted=rollover||mode===3||(mode!==1||!f.extended)&&(mode!==2||f.extended)&&filters.some(filter=>this.matches(f,filter,mask));if(!accepted)continue;if(r[44]&(1<<index)){if(index===0&&(r[0x60]&4)){rollover=true;continue;}r[45]|=index?128:64;r[44]|=32;return false;}r.set(f.raw.slice(0,5),a+1);r[a+5]=(f.dlc&15)|(f.rtr?64:0);if(!f.rtr)r.set(f.raw.slice(5,5+f.dlc),a+6);r[a]=(r[a]&~8)|(f.rtr?8:0);r[44]|=1<<index;this.received++;return true;}return false;}
 put(a,v){if([14,28,29].includes(a))return;this.r[a]=v;if(a===15){this.r[14]=(this.r[14]&31)|(v&0xe0);if(v&16){for(const index of this.pending.keys()){this.r[0x30+index*16]=(this.r[0x30+index*16]&~8)|64;}this.pending.clear();}}if([0x30,0x40,0x50].includes(a)&&v&8)this.transmit((a-0x30)/16);}
 status(){const r=this.r;return(r[44]&3)|[0,1,2].reduce((v,i)=>v|((r[0x30+16*i]&8)?4<<(i*2):0)|((r[44]&(4<<i))?8<<(i*2):0),0);}
 transfer(v){if(this.op===null){this.op=v;this.phase=0;if(v===0xc0){this.reset();this.op=v;}else if((v&0xf8)===0x80){for(let i=0;i<3;i++)if(v&(1<<i))this.transmit(i);}else if((v&0xf8)===0x40)this.addr=0x31+((v>>1)&3)*16+(v&1?5:0);else if((v&0xf9)===0x90){const i=(v>>2)&1;this.addr=0x61+i*16+(v&2?5:0);this.clearRX=i;return this.tx=this.r[this.addr];}return this.tx=v===0xa0?this.status():v===0xb0?((this.r[44]&3)<<6):255;}this.phase++;if([0xa0,0xb0].includes(this.op))return this.tx=this.op===0xa0?this.status():((this.r[44]&3)<<6);if(this.op===3){if(this.phase===1)this.addr=v;else this.addr=(this.addr+1)&255;return this.tx=this.r[this.addr];}if((this.op&0xf9)===0x90)return this.tx=this.r[++this.addr&255];if(this.op===2){if(this.phase===1)this.addr=v;else this.put(this.addr++&255,v);}else if((this.op&0xf8)===0x40){if(this.addr<0x60)this.put(this.addr++,v);}else if(this.op===5){if(this.phase===1)this.addr=v;else if(this.phase===2)this.mask=v;else this.put(this.addr,(this.r[this.addr]&~this.mask)|(v&this.mask));}return this.tx=255;}
 drivers(){return this.r[43]&this.r[44]?[{pin:'INT',voltage:0,ohms:50}]:[];}
 state(){return{mode:this.mode,frames:this.frames,received:this.received,interrupt:this.r[44],loopback:this.mode===2,bitrate:this.bitrate,tec:this.r[28],rec:this.r[29],errorFlags:this.r[45],pending:this.pending.size};}
}
export function attachCANNetwork(cpu,engine,getStates,refresh){let scheduled=false,disposed=false;const active=new Set();
 const connected=(a,b)=>{const n=engine.solution.netlist;return n.same(a.id+':CANH',b.id+':CANH')&&n.same(a.id+':CANL',b.id+':CANL')&&!n.same(a.id+':CANH',a.id+':CANL');};
 const arbitrate=f=>{const sid=f.extended?Math.floor(f.id/262144):f.id;return sid*1048576+(f.extended?524288+f.id%262144*2+(f.rtr?1:0):f.rtr?262144:0);};
 const request=()=>{if(scheduled||disposed)return;scheduled=true;cpu.addClockEvent(run,1);};
 const run=()=>{scheduled=false;if(disposed)return;const states=[...getStates().values()].filter(d=>d.type==='mcp2515'&&d.powered);for(const d of states){d.controller.onRequest=request;if(!d.controller.pending.size||active.has(d.id)||![0,2].includes(d.controller.mode)||d.controller.r[28]>=255)continue;const peers=d.controller.mode===2?[]:states.filter(p=>p.id!==d.id&&connected(d,p)),group=[d,...peers];if(group.some(p=>active.has(p.id)))continue;const entries=group.filter(p=>p.controller.mode===0||p===d&&p.controller.mode===2).flatMap(p=>[...p.controller.pending.values()].map(f=>({p,f}))).sort((a,b)=>arbitrate(a.f)-arbitrate(b.f)||b.p.controller.r[0x30+b.f.index*16]%4-a.p.controller.r[0x30+a.f.index*16]%4);const winner=entries[0];if(!winner)continue;for(const loser of entries.slice(1))loser.p.controller.r[0x30+16*loser.f.index]|=32;const {p,f}=winner,c=p.controller;group.forEach(p=>active.add(p.id));const ack=c.mode===2||group.some(x=>x.id!==p.id&&x.controller.mode===0&&Math.abs(x.controller.bitrate-c.bitrate)<c.bitrate*.015);const bits=(f.extended?67:47)+(f.rtr?0:8*f.dlc),duration=Math.ceil((bits+Math.floor((bits-10)/5)+3)/c.bitrate*16000000);cpu.addClockEvent(()=>{if(disposed)return;if(c.mode===2)c.receive(f,true);else if(ack)for(const other of group)if(other.id!==p.id&&other.powered&&Math.abs(other.controller.bitrate-c.bitrate)<c.bitrate*.015)other.controller.receive(f);c.finish(f,ack);group.forEach(p=>active.delete(p.id));refresh();request();},duration);}};
 return{update(){for(const d of getStates().values())if(d.type==='mcp2515')d.controller.onRequest=request;request();},dispose(){disposed=true;}};
}
